-- ============================================================================
-- 0003_careers_expansion.sql
--
-- Memperluas knowledge base dari 35 profesi IT ke 9 sektor.
--
--   * 9 industri sebagai tabel tersendiri, dihubungkan many-to-many.
--     Ini penting: "Teknologi Informasi" dan "Kreatif" adalah FUNGSI pekerjaan,
--     sedangkan "Perbankan", "Healthcare", "FMCG", "E-commerce", "Energi", dan
--     "Manufaktur" adalah INDUSTRI. Satu Data Analyst bekerja di enam-enamnya.
--     Kalau industri jadi satu kolom, profesi itu harus diduplikasi enam kali.
--
--   * Nama profesi memakai istilah yang benar-benar dipakai di pasar kerja
--     Indonesia, bukan terjemahan harfiah O*NET. Nama asli O*NET tetap
--     disimpan di `name_en` untuk penelusuran.
--
--   * `relevance` menandai profesi yang tidak nyata di Indonesia. Barisnya
--     tetap disimpan (data tidak dibuang) tapi `is_active = false`, jadi tidak
--     pernah muncul di rekomendasi sampai admin menyalakannya.
--
--   * Gaji SENGAJA dikosongkan untuk profesi baru. `salary_source` dan
--     `salary_confidence` memaksa setiap angka gaji menyebut asalnya. Lebih
--     baik tidak menampilkan apa pun daripada menampilkan angka pasar AS
--     kepada siswa Indonesia.
--
-- Sumber nama okupasi & Job Zone: O*NET 30.3 (USDOL/ETA, CC BY 4.0).
-- Penamaan Indonesia: kurasi manual, ditandai per baris di kolom `note`.
-- ============================================================================

begin;

-- ---------------------------------------------------------------------------
-- 1. Industri
-- ---------------------------------------------------------------------------
create table if not exists public.industries (
  code           text primary key,
  name_id        text     not null,
  icon           text,
  display_order  smallint not null
);

insert into public.industries (code, name_id, icon, display_order) values
  ('TECH', 'Teknologi Informasi', '💻', 1),
  ('FINANCE', 'Perbankan & Fintech', '💰', 2),
  ('HEALTH', 'Healthcare', '🏥', 3),
  ('COMMERCE', 'E-commerce & Perdagangan', '🛒', 4),
  ('FMCG', 'FMCG', '🛍', 5),
  ('EDUCATION', 'Pendidikan', '🎓', 6),
  ('ENERGY', 'Energi & Pertambangan', '⚡', 7),
  ('MANUFACTURING', 'Manufaktur & Otomotif', '🏭', 8),
  ('CREATIVE', 'Kreatif & Media Digital', '🎨', 9)
on conflict (code) do update set name_id = excluded.name_id, icon = excluded.icon;

-- ---------------------------------------------------------------------------
-- 2. Kolom baru di careers
-- ---------------------------------------------------------------------------
alter table public.careers add column if not exists soc_code           text;
alter table public.careers add column if not exists name_en            text;
alter table public.careers add column if not exists name_alt           text;
alter table public.careers add column if not exists job_zone           smallint;
alter table public.careers add column if not exists relevance          text
  check (relevance in ('umum','terbatas','tidak_relevan'));
alter table public.careers add column if not exists source             text;
alter table public.careers add column if not exists is_active          boolean not null default true;
alter table public.careers add column if not exists salary_source      text;
alter table public.careers add column if not exists salary_confidence  text
  check (salary_confidence in ('high','medium','low','none'));
alter table public.careers add column if not exists curation_note      text;

comment on column public.careers.relevance is
  'Seberapa nyata profesi ini di pasar kerja Indonesia. tidak_relevan -> is_active false.';
comment on column public.careers.salary_confidence is
  'none = belum ada data gaji Indonesia. Jangan tampilkan rentang gaji saat none.';
comment on column public.careers.name_alt is
  'Istilah alternatif untuk pencarian, dipisah titik koma.';

-- 35 profesi IT yang sudah ada: tandai asal-usulnya
update public.careers set
  source = coalesce(source, 'linkedin_id'),
  relevance = coalesce(relevance, 'umum'),
  salary_source = coalesce(salary_source, 'scraping_linkedin_2025'),
  salary_confidence = coalesce(salary_confidence, 'medium')
where source is null;

-- Isi soc_code dan job_zone dari pemetaan di 0002
update public.careers c set soc_code = m.soc_code
from public.career_onet_map m where m.career_id = c.id and c.soc_code is null;

-- ---------------------------------------------------------------------------
-- 3. Impor profesi baru
--
--    SOC yang sudah dipakai 35 profesi IT sengaja dilewati: daftar mereka
--    lebih granular daripada O*NET (Frontend / Backend / Fullstack Developer
--    semuanya memetakan ke 15-1252.00), dan granularitas itu lebih berguna
--    untuk user Indonesia daripada satu baris "Software Developer".
-- ---------------------------------------------------------------------------
-- Satu baris per SOC untuk sumber 'onet'. Indeks parsial ini yang membuat
-- migration aman dijalankan ulang.
create unique index if not exists uq_careers_onet_soc
  on public.careers (soc_code) where source = 'onet';

insert into public.careers
  (career_name, career_description, min_education_rank, location_bias,
   salary_min, salary_max, soc_code, name_en, name_alt, job_zone,
   relevance, source, is_active, salary_source, salary_confidence, curation_note)
