  ('Manajer Keuangan', 'Plan, direct, or coordinate accounting, investing, banking, insurance, securities, and other financial activities of a branch, office, or department of an establishment.', 4, NULL, NULL, NULL, '11-3031.00', 'Financial Managers', 'Finance Manager', 4, 'umum', 'onet', true, NULL, 'none', NULL),
