  ('Manajer Investasi', 'Plan, direct, or coordinate investment strategy or operations for a large pool of liquid assets supplied by institutional investors or individual investors.', 5, NULL, NULL, NULL, '11-3031.03', 'Investment Fund Managers', 'Fund Manager;Portfolio Manager', 5, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Manajer Produksi', 'Plan, direct, or coordinate the work activities and resources necessary for manufacturing products in accordance with cost, quality, and quantity specifications.', 4, NULL, NULL, NULL, '11-3051.00', 'Industrial Production Managers', 'Production Manager;Plant Manager', 4, 'umum', 'onet', true, NULL, 'none', NULL),
