  ('Talent Director / Casting Director', 'Audition and interview performers to select most appropriate talent for parts in stage, television, radio, or motion picture productions.', 4, NULL, NULL, NULL, '27-2012.04', 'Talent Directors', 'Casting Director', 4, 'terbatas', 'onet', true, NULL, 'none', 'Peran casting ada di industri film/TV/iklan Indonesia tapi jumlah posisi sedikit; perlu verifikasi istilah baku.'),
  ('Technical Director / Manajer Teknis Siaran', 'Coordinate activities of technical departments, such as taping, editing, engineering, and maintenance, to produce radio or television programs.', 4, NULL, NULL, NULL, '27-2012.05', 'Media Technical Directors/Managers', 'Media Technical Manager', 4, 'terbatas', 'onet', true, NULL, 'none', 'Niche, ada di stasiun TV/radio atau rumah produksi besar.'),
  ('Music Director dan Komposer', 'Conduct, direct, plan, and lead instrumental or vocal performances by musical artists or groups, such as orchestras, bands, choirs, and glee clubs; or create original works of music.', 4, NULL, NULL, NULL, '27-2041.00', 'Music Directors and Composers', 'Komposer;Arranger;Dirigen', 4, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Penyiar Radio/TV', 'Speak or read from scripted materials, such as news reports or commercial messages, on radio, television, or other communications media. May play and queue music, announce artist or title of performance, identify station, or interview guests.', 4, NULL, NULL, NULL, '27-3011.00', 'Broadcast Announcers and Radio Disc Jockeys', 'Announcer;Radio DJ', 4, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Wartawan / Jurnalis', 'Narrate or write news stories, reviews, or commentary for print, broadcast, or other communications media such as newspapers, magazines, radio, or television. May collect and analyze information through interview, investigation, or observation.', 4, NULL, NULL, NULL, '27-3023.00', 'News Analysts, Reporters, and Journalists', 'Reporter;News Analyst', 4, 'umum', 'onet', true, NULL, 'none', NULL),
  ('PR Specialist / Humas', 'Promote or create an intended public image for individuals, groups, or organizations. May write or select material for release to various communications media. May specialize in using social media.', 4, NULL, NULL, NULL, '27-3031.00', 'Public Relations Specialists', 'Public Relations Officer', 4, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Redaktur / Editor', 'Plan, coordinate, revise, or edit written material. May review proposals and drafts for possible publication.', 4, NULL, NULL, NULL, '27-3041.00', 'Editors', 'Editor Naskah;Editor Konten', 4, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Penulis', 'Originate and prepare written material, such as scripts, stories, advertisements, and other material.', 4, NULL, NULL, NULL, '27-3043.00', 'Writers and Authors', 'Writer;Content Writer;Penulis Naskah', 4, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Penyair / Pencipta Lirik', 'Create original written works, such as scripts, essays, prose, poetry or song lyrics, for publication or performance.', 4, NULL, NULL, NULL, '27-3043.05', 'Poets, Lyricists and Creative Writers', 'Poet;Lyricist;Penulis Lirik', 4, 'terbatas', 'onet', true, NULL, 'none', 'Umumnya berkarier independen/freelance, bukan posisi lowongan formal.'),
  ('Penerjemah / Juru Bahasa', 'Interpret oral or sign language, or translate written text from one language into another.', 4, NULL, NULL, NULL, '27-3091.00', 'Interpreters and Translators', 'Translator;Interpreter', 4, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Juru Ketik Notulen Sidang / Captioner', 'Use verbatim methods and equipment to capture, store, retrieve, and transcribe pretrial and trial proceedings or other information. Includes stenocaptioners who operate computerized stenographic captioning equipment to provide captions of live or prerecorded broadcasts for hearing-impaired viewers.', 3, NULL, NULL, NULL, '27-3092.00', 'Court Reporters and Simultaneous Captioners', 'Stenographer;Live Captioner', 3, 'tidak_relevan', 'onet', false, NULL, 'none', 'Sistem pengadilan Indonesia memakai panitera, bukan court reporter stenografi verbatim; live captioning untuk siaran TV ada tapi sangat niche - perlu verifikasi.'),
  ('Pekerja Media dan Komunikasi Lainnya', 'All media and communication workers not listed separately.', 3, NULL, NULL, NULL, '27-3099.00', 'Media and Communication Workers, All Other', NULL, NULL, 'terbatas', 'onet', true, NULL, 'none', 'Kategori sisa (catch-all) O*NET; tidak ada padanan spesifik.'),
  ('Teknisi Audio Video', 'Set up, maintain, and dismantle audio and video equipment, such as microphones, sound speakers, connecting wires and cables, sound and mixing boards, video cameras, video monitors and servers, and related electronic equipment for live or recorded events, such as concerts, meetings, conventions, pres', 3, NULL, NULL, NULL, '27-4011.00', 'Audio and Video Technicians', 'AV Technician', 3, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Teknisi Broadcast/Penyiaran', 'Set up, operate, and maintain the electronic equipment used to acquire, edit, and transmit audio and video for radio or television programs. Control and adjust incoming and outgoing broadcast signals to regulate sound volume, signal strength, and signal clarity. Operate satellite, microwave, or othe', 3, NULL, NULL, NULL, '27-4012.00', 'Broadcast Technicians', 'Broadcast Engineer', 3, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Sound Engineer', 'Assemble and operate equipment to record, synchronize, mix, edit, or reproduce sound, including music, voices, or sound effects, for theater, video, film, television, podcasts, sporting events, and other productions.', 3, NULL, NULL, NULL, '27-4014.00', 'Sound Engineering Technicians', 'Penata Suara;Audio Engineer', 3, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Penata Cahaya (Lighting Technician)', 'Set up, maintain, and dismantle light fixtures, lighting control devices, and the associated lighting electrical and rigging equipment used for photography, television, film, video, and live productions. May focus or operate light fixtures, or attach color filters or other lighting accessories.', 3, NULL, NULL, NULL, '27-4015.00', 'Lighting Technicians', 'Lighting Man;Gaffer', 3, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Fotografer', 'Photograph people, landscapes, merchandise, or other subjects. May use lighting equipment to enhance a subject''s appearance. May use editing software to produce finished images and prints. Includes commercial and industrial photographers, scientific photographers, and photojournalists.', 3, NULL, NULL, NULL, '27-4021.00', 'Photographers', 'Photographer', 3, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Juru Kamera (Camera Person)', 'Operate television, video, or film camera to record images or scenes for television, video, or film productions.', 3, NULL, NULL, NULL, '27-4031.00', 'Camera Operators, Television, Video, and Film', 'Cameraman;Camera Operator', 3, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Video Editor', 'Edit moving images on film, video, or other media. May work with a producer or director to organize images for final production. May edit or synchronize soundtracks with images.', 4, NULL, NULL, NULL, '27-4032.00', 'Film and Video Editors', 'Film Editor;Editor Video', 4, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Pekerja Peralatan Media dan Komunikasi Lainnya', 'All media and communication equipment workers not listed separately.', 3, NULL, NULL, NULL, '27-4099.00', 'Media and Communication Equipment Workers, All Other', NULL, NULL, 'terbatas', 'onet', true, NULL, 'none', 'Kategori sisa (catch-all) O*NET; tidak ada padanan spesifik.'),
  ('Chiropractor', 'Assess, treat, and care for patients by manipulation of spine and musculoskeletal system. May provide spinal adjustment or address sacral or pelvic misalignment.', 5, NULL, NULL, NULL, '29-1011.00', 'Chiropractors', 'Ahli Kiropraktik; Kiropraktor', 5, 'terbatas', 'onet', true, NULL, 'none', 'Kiropraktik belum jadi profesi kesehatan berizin resmi Kemenkes RI; layanan hanya ada di klinik swasta tertentu di kota besar.'),
  ('Dokter Gigi', 'Examine, diagnose, and treat diseases, injuries, and malformations of teeth and gums. May treat diseases of nerve, pulp, and other dental tissues affecting oral hygiene and retention of teeth. May fit dental appliances or provide preventive care.', 5, NULL, NULL, NULL, '29-1021.00', 'Dentists, General', 'Dentist', 5, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Dokter Gigi Spesialis Bedah Mulut dan Maksilofasial', 'Perform surgery and related procedures on the hard and soft tissues of the oral and maxillofacial regions to treat diseases, injuries, or defects. May diagnose problems of the oral and maxillofacial regions. May perform surgery to improve function or appearance.', 5, NULL, NULL, NULL, '29-1022.00', 'Oral and Maxillofacial Surgeons', 'Sp.BM; Oral Maxillofacial Surgeon', 5, 'terbatas', 'onet', true, NULL, 'none', 'Spesialisasi resmi PDGI (Sp.BM), tapi jumlah praktisi sedikit dan terpusat di RS besar/kota besar.'),
  ('Dokter Gigi Spesialis Ortodonti', 'Examine, diagnose, and treat dental malocclusions and oral cavity anomalies. Design and fabricate appliances to realign teeth and jaws to produce and maintain normal function and to improve appearance.', 5, NULL, NULL, NULL, '29-1023.00', 'Orthodontists', 'Sp.Ort; Dokter Behel', 5, 'umum', 'onet', true, NULL, 'none', 'Permintaan tinggi (perawatan kawat gigi/behel populer).'),
  ('Dokter Gigi Spesialis Prostodonsia', 'Diagnose, treat, rehabilitate, design, and fit prostheses that maintain oral function, health, and appearance for patients with clinical conditions associated with teeth, oral and maxillofacial tissues, or the jaw.', 5, NULL, NULL, NULL, '29-1024.00', 'Prosthodontists', 'Sp.Pros', 5, 'terbatas', 'onet', true, NULL, 'none', 'Spesialisasi resmi tapi jumlah praktisi sangat sedikit, terpusat di kota besar.'),
  ('Dokter Gigi Spesialis Lainnya', 'All dentists not listed separately.', 3, NULL, NULL, NULL, '29-1029.00', 'Dentists, All Other Specialists', 'Sp.KG; Sp.Perio; Sp.PM; Sp.RKG', NULL, 'umum', 'onet', true, NULL, 'none', 'Mencakup spesialisasi gigi lain seperti konservasi gigi, periodonsia, kedokteran gigi anak, radiologi kedokteran gigi.'),
  ('Ahli Gizi', 'Plan and conduct food service or nutritional programs to assist in the promotion of health and control of disease. May supervise activities of a department providing quantity food services, counsel individuals, or conduct nutritional research.', 5, NULL, NULL, NULL, '29-1031.00', 'Dietitians and Nutritionists', 'Nutrisionis; Dietisien; Dietitian', 5, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Optometris', 'Diagnose, manage, and treat conditions and diseases of the human eye and visual system. Examine eyes and visual system, diagnose problems or impairments, prescribe corrective lenses, and provide treatment. May prescribe therapeutic drugs to treat specific eye conditions.', 5, NULL, NULL, NULL, '29-1041.00', 'Optometrists', 'Refraksionis Optisien; RO', 5, 'umum', 'onet', true, NULL, 'none', 'Sebagian layanan dijalankan oleh Refraksionis Optisien (RO) di gerai optik, sebagian oleh lulusan D4 Optometri.'),
  ('Apoteker', 'Dispense drugs prescribed by physicians and other health practitioners and provide information to patients about medications and their use. May advise physicians and other health practitioners on the selection, dosage, interactions, and side effects of medications.', 5, NULL, NULL, NULL, '29-1051.00', 'Pharmacists', 'Pharmacist', 5, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Physician Assistant', 'Provide healthcare services typically performed by a physician, under the supervision of a physician. Conduct complete physicals, provide treatment, and counsel patients. May, in some cases, prescribe medication. Must graduate from an accredited educational program for physician assistants.', 5, NULL, NULL, NULL, '29-1071.00', 'Physician Assistants', 'Asisten Dokter', 5, 'tidak_relevan', 'onet', false, NULL, 'none', 'Tidak ada profesi ''asisten dokter'' berizin mandiri di Indonesia; sistem kesehatan memisahkan dokter dan perawat/bidan tanpa jenjang ini.'),
  ('Anesthesiologist Assistant', 'Assist anesthesiologists in the administration of anesthesia for surgical and non-surgical procedures. Monitor patient status and provide patient care during surgical treatment.', 5, NULL, NULL, NULL, '29-1071.01', 'Anesthesiologist Assistants', 'Asisten Anestesi', 5, 'tidak_relevan', 'onet', false, NULL, 'none', 'Tidak ada profesi ini di Indonesia; peran serupa dijalankan oleh Penata Anestesi (perawat anestesi), bukan kategori terpisah.'),
  ('Podiatris', 'Diagnose and treat diseases and deformities of the human foot.', 5, NULL, NULL, NULL, '29-1081.00', 'Podiatrists', 'Podiatrist; Dokter Kaki', 5, 'tidak_relevan', 'onet', false, NULL, 'none', 'Podiatri bukan profesi kesehatan tersendiri di Indonesia; kondisi kaki ditangani dokter spesialis ortopedi/kulit atau perawat luka.'),
  ('Terapis Okupasi', 'Assess, plan, and organize rehabilitative programs that help build or restore vocational, homemaking, and daily living skills, as well as general independence, to persons with disabilities or developmental delays. Use therapeutic techniques, adapt the individual''s environment, teach skills, and modi', 5, NULL, NULL, NULL, '29-1122.00', 'Occupational Therapists', 'Occupational Therapist', 5, 'terbatas', 'onet', true, NULL, 'none', 'Profesi resmi ada tapi jumlah praktisi masih sedikit dibanding fisioterapis, umumnya di RS rehabilitasi kota besar.'),
  ('Terapis Low Vision dan Rehabilitasi Penglihatan', 'Provide therapy to patients with visual impairments to improve their functioning in daily life activities. May train patients in activities such as computer use, communication skills, or home management skills.', 5, NULL, NULL, NULL, '29-1122.01', 'Low Vision Therapists, Orientation and Mobility Specialists, and Vision Rehabilitation Therapists', 'Vision Rehabilitation Therapist', 5, 'tidak_relevan', 'onet', false, NULL, 'none', 'Tidak ada profesi terpisah ini di Indonesia; fungsinya melebur ke terapi okupasi atau layanan optometri/oftalmologi.'),
  ('Fisioterapis', 'Assess, plan, organize, and participate in rehabilitative programs that improve mobility, relieve pain, increase strength, and improve or correct disabling conditions resulting from disease or injury.', 5, NULL, NULL, NULL, '29-1123.00', 'Physical Therapists', 'Physical Therapist', 5, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Radiografer Radioterapi', 'Provide radiation therapy to patients as prescribed by a radiation oncologist according to established practices and standards. Duties may include reviewing prescription and diagnosis; acting as liaison with physician and supportive care personnel; preparing equipment, such as immobilization, treatm', 3, NULL, NULL, NULL, '29-1124.00', 'Radiation Therapists', 'Radiation Therapist', 3, 'terbatas', 'onet', true, NULL, 'none', 'Di Indonesia fungsi ini umumnya dijalankan oleh Radiografer dengan peminatan radioterapi, bukan profesi terpisah.'),
  ('Terapis Rekreasi', 'Plan, direct, or coordinate medically-approved recreation programs for patients in hospitals, nursing homes, or other institutions. Activities include sports, trips, dramatics, social activities, and crafts. May assess a patient condition and recommend appropriate recreational activity.', 4, NULL, NULL, NULL, '29-1125.00', 'Recreational Therapists', 'Recreational Therapist', 4, 'tidak_relevan', 'onet', false, NULL, 'none', 'Tidak ada profesi terpisah ini di Indonesia; aktivitas rekreasi terapeutik biasanya bagian dari tugas perawat/terapis okupasi.'),
  ('Terapis Respirasi', 'Assess, treat, and care for patients with breathing disorders. Assume primary responsibility for all respiratory care modalities, including the supervision of respiratory therapy technicians. Initiate and conduct therapeutic procedures; maintain patient records; and select, assemble, check, and oper', 3, NULL, NULL, NULL, '29-1126.00', 'Respiratory Therapists', 'Respiratory Therapist; Fisioterapis Respirasi', 3, 'terbatas', 'onet', true, NULL, 'none', 'Belum jadi profesi mandiri yang luas; fungsi biasanya ditangani perawat ICU, dokter spesialis paru, atau fisioterapis respirasi.'),
  ('Terapis Wicara', 'Assess and treat persons with speech, language, voice, and fluency disorders. May select alternative communication systems and teach their use. May perform research related to speech and language problems.', 5, NULL, NULL, NULL, '29-1127.00', 'Speech-Language Pathologists', 'Speech-Language Pathologist', 5, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Fisiolog Olahraga', 'Assess, plan, or implement fitness programs that include exercise or physical activities such as those designed to improve cardiorespiratory function, body composition, muscular strength, muscular endurance, or flexibility.', 4, NULL, NULL, NULL, '29-1128.00', 'Exercise Physiologists', 'Exercise Physiologist; Ahli Fisiologi Latihan', 4, 'terbatas', 'onet', true, NULL, 'none', 'perlu verifikasi - belum jadi profesi berizin terpisah; overlap dengan lulusan Ilmu Keolahragaan atau fisioterapi olahraga.'),
  ('Terapis Lainnya', 'All therapists not listed separately.', 3, NULL, NULL, NULL, '29-1129.00', 'Therapists, All Other', 'Other Therapists', NULL, 'umum', 'onet', true, NULL, 'none', 'Kategori sisa (catch-all) untuk terapis yang tidak masuk kelompok lain.'),
  ('Terapis Seni', 'Plan or conduct art therapy sessions or programs to improve clients'' physical, cognitive, or emotional well-being.', 5, NULL, NULL, NULL, '29-1129.01', 'Art Therapists', 'Art Therapist', 5, 'terbatas', 'onet', true, NULL, 'none', 'Ada praktik di sejumlah klinik kesehatan jiwa/pendidikan khusus, tapi belum ada regulasi profesi resmi tersendiri.'),
  ('Terapis Musik', 'Plan, organize, direct, or assess clinical and evidenced-based music therapy interventions to positively influence individuals'' physical, psychological, cognitive, or behavioral status.', 4, NULL, NULL, NULL, '29-1129.02', 'Music Therapists', 'Music Therapist', 4, 'terbatas', 'onet', true, NULL, 'none', 'Ada praktik di klinik tumbuh kembang/kesehatan jiwa tertentu, tapi belum ada regulasi profesi resmi tersendiri.'),
  ('Dokter Hewan', 'Diagnose, treat, or research diseases and injuries of animals. Includes veterinarians who conduct research and development, inspect livestock, or care for pets and companion animals.', 5, NULL, NULL, NULL, '29-1131.00', 'Veterinarians', 'Veterinarian', 5, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Perawat', 'Assess patient health problems and needs, develop and implement nursing care plans, and maintain medical records. Administer nursing care to ill, injured, convalescent, or disabled patients. May advise patients on health maintenance and disease prevention or provide case management. Licensing or reg', 4, NULL, NULL, NULL, '29-1141.00', 'Registered Nurses', 'Registered Nurse; Ners', 4, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Perawat Perawatan Akut', 'Provide advanced nursing care for patients with acute conditions such as heart attacks, respiratory distress syndrome, or shock. May care for pre- and post-operative patients or perform advanced, invasive diagnostic or therapeutic procedures.', 4, NULL, NULL, NULL, '29-1141.01', 'Acute Care Nurses', 'Perawat ICU/IGD; Acute Care Nurse', 4, 'terbatas', 'onet', true, NULL, 'none', 'O*NET memecah lebih detail dari praktik Indonesia; peran ini umumnya disebut Perawat ICU atau Perawat Gawat Darurat.'),
  ('Perawat Spesialis Jiwa', 'Assess, diagnose, and treat individuals and families with mental health or substance use disorders or the potential for such disorders. Apply therapeutic activities, including the prescription of medication, per state regulations, and the administration of psychotherapy.', 5, NULL, NULL, NULL, '29-1141.02', 'Advanced Practice Psychiatric Nurses', 'Ners Spesialis Keperawatan Jiwa', 5, 'terbatas', 'onet', true, NULL, 'none', 'Jenjang Ners Spesialis Keperawatan Jiwa masih terbatas jumlahnya dan program pendidikannya baru berkembang.'),
  ('Perawat Kritis', 'Provide specialized nursing care for patients in critical or coronary care units.', 4, NULL, NULL, NULL, '29-1141.03', 'Critical Care Nurses', 'Perawat ICU; Critical Care Nurse', 4, 'terbatas', 'onet', true, NULL, 'none', 'Umumnya disebut Perawat ICU/Perawatan Intensif, bukan jenjang lisensi terpisah seperti di AS.'),
  ('Perawat Klinis Spesialis', 'Direct nursing staff in the provision of patient care in a clinical practice setting, such as a hospital, hospice, clinic, or home. Ensure adherence to established clinical policies, protocols, regulations, and standards.', 5, NULL, NULL, NULL, '29-1141.04', 'Clinical Nurse Specialists', 'Ners Spesialis; Clinical Nurse Specialist', 5, 'terbatas', 'onet', true, NULL, 'none', 'Ners Spesialis klinis masih jenjang baru dan jumlah lulusannya sedikit.'),
  ('Penata Anestesi', 'Administer anesthesia, monitor patient''s vital signs, and oversee patient recovery from anesthesia. May assist anesthesiologists, surgeons, other physicians, or dentists. Must be registered nurses who have specialized graduate education.', 5, NULL, NULL, NULL, '29-1151.00', 'Nurse Anesthetists', 'Perawat Anestesi; Nurse Anesthetist', 5, 'umum', 'onet', true, NULL, 'none', 'Profesi resmi dengan pendidikan D4 Keperawatan Anestesiologi; banyak bertugas di kamar operasi RS.'),
  ('Bidan', 'Diagnose and coordinate all aspects of the birthing process, either independently or as part of a healthcare team. May provide well-woman gynecological care. Must have specialized, graduate nursing education.', 5, NULL, NULL, NULL, '29-1161.00', 'Nurse Midwives', 'Nurse Midwife', 5, 'umum', 'onet', true, NULL, 'none', 'Di AS nurse-midwife adalah perawat dengan pendidikan lanjutan; di Indonesia Bidan adalah profesi mandiri terpisah dari keperawatan.'),
  ('Nurse Practitioner', 'Diagnose and treat acute, episodic, or chronic illness, independently or as part of a healthcare team. May focus on health promotion and disease prevention. May order, perform, or interpret diagnostic tests such as lab work and x rays. May prescribe medication. Must be registered nurses who have spe', 5, NULL, NULL, NULL, '29-1171.00', 'Nurse Practitioners', 'Perawat Praktisi Lanjutan', 5, 'tidak_relevan', 'onet', false, NULL, 'none', 'Tidak ada jenjang perawat dengan kewenangan mendiagnosis dan meresepkan obat secara mandiri seperti di AS; regulasi keperawatan Indonesia tidak mengenal peran ini.'),
  ('Audiolog', 'Assess and treat persons with hearing and related disorders. May fit hearing aids and provide auditory training. May perform research related to hearing problems.', 5, NULL, NULL, NULL, '29-1181.00', 'Audiologists', 'Audiologist', 5, 'terbatas', 'onet', true, NULL, 'none', 'Profesi resmi ada tapi jumlah praktisi sedikit, umumnya di RS THT rujukan kota besar.'),
  ('Dokter Spesialis Anestesi', 'Administer anesthetics and analgesics for pain management prior to, during, or after surgery.', 5, NULL, NULL, NULL, '29-1211.00', 'Anesthesiologists', 'Sp.An; Anesthesiologist', 5, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Dokter Spesialis Jantung dan Pembuluh Darah', 'Diagnose, treat, manage, and prevent diseases or conditions of the cardiovascular system. May further subspecialize in interventional procedures (e.g., balloon angioplasty and stent placement), echocardiography, or electrophysiology.', 5, NULL, NULL, NULL, '29-1212.00', 'Cardiologists', 'Sp.JP; Kardiolog', 5, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Dokter Spesialis Kulit dan Kelamin', 'Diagnose and treat diseases relating to the skin, hair, and nails. May perform both medical and dermatological surgery functions.', 5, NULL, NULL, NULL, '29-1213.00', 'Dermatologists', 'Sp.KK; Sp.DV; Dermatolog', 5, 'umum', 'onet', true, NULL, 'none', 'Nomenklatur baru IDI menyebutnya Sp.DV (Dermatologi dan Venereologi).'),
  ('Dokter Spesialis Kedokteran Gawat Darurat', 'Make immediate medical decisions and act to prevent death or further disability. Provide immediate recognition, evaluation, care, stabilization, and disposition of patients. May direct emergency medical staff in an emergency department.', 5, NULL, NULL, NULL, '29-1214.00', 'Emergency Medicine Physicians', 'Sp.GD; Sp.EM', 5, 'umum', 'onet', true, NULL, 'none', 'perlu verifikasi singkatan gelar resmi terbaru - spesialisasi ini relatif baru di Indonesia.'),
  ('Dokter Umum', 'Diagnose, treat, and provide preventive care to individuals and families across the lifespan. May refer patients to specialists when needed for further diagnosis or treatment.', 5, NULL, NULL, NULL, '29-1215.00', 'Family Medicine Physicians', 'Dokter Keluarga; General Practitioner', 5, 'umum', 'onet', true, NULL, 'none', 'O*NET memecah lebih halus; di Indonesia peran ini dijalankan Dokter Umum di puskesmas/klinik, bukan spesialisasi tersendiri yang lazim dipraktikkan luas.'),
  ('Dokter Spesialis Penyakit Dalam', 'Diagnose and provide nonsurgical treatment for a wide range of diseases and injuries of internal organ systems. Provide care mainly for adults and adolescents, and are based primarily in an outpatient care setting.', 5, NULL, NULL, NULL, '29-1216.00', 'General Internal Medicine Physicians', 'Sp.PD', 5, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Dokter Spesialis Saraf', 'Diagnose, manage, and treat disorders and diseases of the brain, spinal cord, and peripheral nerves, with a primarily nonsurgical focus.', 5, NULL, NULL, NULL, '29-1217.00', 'Neurologists', 'Sp.N; Neurolog', 5, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Dokter Spesialis Obstetri dan Ginekologi', 'Provide medical care related to pregnancy or childbirth. Diagnose, treat, and help prevent diseases of women, particularly those affecting the reproductive system. May also provide general care to women. May perform both medical and gynecological surgery functions.', 5, NULL, NULL, NULL, '29-1218.00', 'Obstetricians and Gynecologists', 'Sp.OG', 5, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Dokter Spesialis Anak', 'Diagnose, treat, and help prevent diseases and injuries in children. May refer patients to specialists for further diagnosis or treatment, as needed.', 5, NULL, NULL, NULL, '29-1221.00', 'Pediatricians, General', 'Sp.A; Pediatrician', 5, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Dokter Spesialis Patologi', 'Diagnose diseases and conduct lab tests using organs, body tissues, and fluids. Includes medical examiners.', 5, NULL, NULL, NULL, '29-1222.00', 'Physicians, Pathologists', 'Sp.PK; Sp.PA', 5, 'umum', 'onet', true, NULL, 'none', 'Di Indonesia dipecah jadi dua spesialisasi terpisah: Patologi Klinik (Sp.PK) dan Patologi Anatomi (Sp.PA).'),
  ('Dokter Spesialis Jiwa', 'Diagnose, treat, and help prevent mental disorders.', 5, NULL, NULL, NULL, '29-1223.00', 'Psychiatrists', 'Sp.KJ; Psikiater', 5, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Dokter Spesialis Radiologi', 'Diagnose and treat diseases and injuries using medical imaging techniques, such as x rays, magnetic resonance imaging (MRI), nuclear medicine, and ultrasounds. May perform minimally invasive medical procedures and tests.', 5, NULL, NULL, NULL, '29-1224.00', 'Radiologists', 'Sp.Rad; Radiolog', 5, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Dokter Spesialis Lainnya', 'All physicians not listed separately.', 3, NULL, NULL, NULL, '29-1229.00', 'Physicians, All Other', 'Other Physicians', NULL, 'umum', 'onet', true, NULL, 'none', 'Kategori sisa (catch-all) untuk dokter spesialis lain.'),
  ('Dokter Spesialis Alergi Imunologi', 'Diagnose, treat, and help prevent allergic diseases and disease processes affecting the immune system.', 5, NULL, NULL, NULL, '29-1229.01', 'Allergists and Immunologists', 'Sp.AI', 5, 'terbatas', 'onet', true, NULL, 'none', 'Subspesialis dari penyakit dalam/anak, jumlah praktisi masih sedikit.'),
  ('Hospitalist', 'Provide inpatient care predominantly in settings such as medical wards, acute care units, intensive care units, rehabilitation centers, or emergency rooms. Manage and coordinate patient care throughout treatment.', 5, NULL, NULL, NULL, '29-1229.02', 'Hospitalists', 'Dokter Jaga Ruangan', 5, 'tidak_relevan', 'onet', false, NULL, 'none', 'Tidak ada profesi terpisah ''hospitalist'' di Indonesia; fungsi serupa dijalankan dokter jaga RS atau Sp.PD.'),
