  ('Akupunkturis', 'Diagnose, treat, and prevent disorders by stimulating specific acupuncture points within the body using acupuncture needles. May also use cups, nutritional supplements, therapeutic massage, acupressure, and other alternative health therapies.', 5, NULL, NULL, NULL, '29-1291.00', 'Acupuncturists', 'Terapis Akupunktur; Acupuncturist', 5, 'terbatas', 'onet', true, NULL, 'none', 'Bagian dari pengobatan tradisional/komplementer; ada juga dokter dengan sertifikasi akupunktur medik.'),
