  ('Tenaga Kesehatan Pemberi Diagnosis/Pengobatan Lainnya', 'All healthcare diagnosing or treating practitioners not listed separately.', 3, NULL, NULL, NULL, '29-1299.00', 'Healthcare Diagnosing or Treating Practitioners, All Other', 'Other Healthcare Practitioners', NULL, 'umum', 'onet', true, NULL, 'none', 'Kategori sisa (catch-all).'),
  ('Dokter Naturopati', 'Diagnose, treat, and help prevent diseases using a system of practice that is based on the natural healing capacity of individuals. May use physiological, psychological or mechanical methods. May also use natural medicines, prescription or legend drugs, foods, herbs, or other natural remedies.', 5, NULL, NULL, NULL, '29-1299.01', 'Naturopathic Physicians', 'Naturopathic Physician', 5, 'tidak_relevan', 'onet', false, NULL, 'none', 'Naturopati tidak diregulasi sebagai profesi kedokteran resmi di Indonesia.'),
