  ('Bidan', 'Provide prenatal care and childbirth assistance.', 5, NULL, NULL, NULL, '29-9099.01', 'Midwives', 'Midwife', 5, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Caregiver Lansia/Homecare', 'Monitor the health status of an individual with disabilities or illness, and address their health-related needs, such as changing bandages, dressing wounds, or administering medication. Work is performed under the direction of offsite or intermittent onsite licensed nursing staff. Provide assistance', 1, NULL, NULL, NULL, '31-1121.00', 'Home Health Aides', 'Perawat Pendamping; Home Health Aide', 2, 'umum', 'onet', true, NULL, 'none', 'Istilah ''caregiver'' dipakai luas untuk perawatan lansia/pasien di rumah.'),
  ('Caregiver Pendamping Pribadi', 'Provide personalized assistance to individuals with disabilities or illness who require help with personal care and activities of daily living support (e.g., feeding, bathing, dressing, grooming, toileting, and ambulation). May also provide help with tasks such as preparing meals, doing light housek', 1, NULL, NULL, NULL, '31-1122.00', 'Personal Care Aides', 'Personal Care Aide', 2, 'umum', 'onet', true, NULL, 'none', 'Overlap dengan Home Health Aide; keduanya umum disebut ''caregiver'' di Indonesia meski O*NET memisahkannya berdasarkan tingkat perawatan medis.'),
  ('Asisten Perawat', 'Provide or assist with basic care or support under the direction of onsite licensed nursing staff. Perform duties such as monitoring of health status, feeding, bathing, dressing, grooming, toileting, or ambulation of patients in a health or nursing facility. May include medication administration and', 3, NULL, NULL, NULL, '31-1131.00', 'Nursing Assistants', 'Pembantu Orang Sakit; POS; Nursing Assistant', 3, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Pekarya Kesehatan', 'Transport patients to areas such as operating rooms or x-ray rooms using wheelchairs, stretchers, or moveable beds. May maintain stocks of supplies or clean and transport equipment. Psychiatric orderlies are included in Psychiatric Aides.', 1, NULL, NULL, NULL, '31-1132.00', 'Orderlies', 'Portir Rumah Sakit; Orderly', 2, 'terbatas', 'onet', true, NULL, 'none', 'perlu verifikasi istilah pasti - peran pengantar pasien/alat di RS, penamaan bervariasi antar rumah sakit.'),
