  ('Asisten Terapis Okupasi', 'Assist occupational therapists in providing occupational therapy treatments and procedures. May, in accordance with state laws, assist in development of treatment plans, carry out routine functions, direct activity programs, and document the progress of treatments. Generally requires formal training', 3, NULL, NULL, NULL, '31-2011.00', 'Occupational Therapy Assistants', 'Occupational Therapy Assistant', 3, 'tidak_relevan', 'onet', false, NULL, 'none', 'Jenjang asisten terpisah tidak umum di Indonesia; terapis okupasi langsung dari lulusan D3/D4 Terapi Okupasi.'),
  ('Pekarya Terapi Okupasi', 'Under close supervision of an occupational therapist or occupational therapy assistant, perform only delegated, selected, or routine tasks in specific situations. These duties include preparing patient and treatment room.', 3, NULL, NULL, NULL, '31-2012.00', 'Occupational Therapy Aides', 'Occupational Therapy Aide', 3, 'tidak_relevan', 'onet', false, NULL, 'none', 'Tidak ada jenjang ini secara terpisah di Indonesia.'),
  ('Asisten Fisioterapis', 'Assist physical therapists in providing physical therapy treatments and procedures. May, in accordance with state laws, assist in the development of treatment plans, carry out routine functions, document the progress of treatment, and modify specific treatments in accordance with patient status and ', 3, NULL, NULL, NULL, '31-2021.00', 'Physical Therapist Assistants', 'Physical Therapist Assistant', 3, 'terbatas', 'onet', true, NULL, 'none', 'Fisioterapi di Indonesia umumnya satu jenjang profesi tanpa lisensi asisten terpisah; istilah ini kadang dipakai informal di klinik.'),
