  ('Operator Kapal Keruk (Dredge)', 'Operate dredge to remove sand, gravel, or other materials in order to excavate and maintain navigable channels in waterways.', 1, NULL, NULL, NULL, '53-7031.00', 'Dredge Operators', 'Dredge Operator', 2, 'umum', 'onet', true, NULL, 'none', 'relevan khususnya untuk tambang timah lepas pantai di Bangka Belitung'),
  ('Operator Hoist dan Winch', 'Operate or tend hoists or winches to lift and pull loads using power-operated cable equipment.', 1, NULL, NULL, NULL, '53-7041.00', 'Hoist and Winch Operators', 'Hoist Operator;Winch Operator', 2, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Operator Truk/Traktor Industri', 'Operate industrial trucks or tractors equipped to move materials around a warehouse, storage yard, factory, construction site, or similar location.', 1, NULL, NULL, NULL, '53-7051.00', 'Industrial Truck and Tractor Operators', 'Forklift Operator;Industrial Truck Operator', 2, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Pekerja Pencuci/Pembersih Kendaraan dan Alat', 'Wash or otherwise clean vehicles, machinery, and other equipment. Use such materials as water, cleaning agents, brushes, cloths, and hoses.', 1, NULL, NULL, NULL, '53-7061.00', 'Cleaners of Vehicles and Equipment', 'Vehicle and Equipment Cleaner', 2, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Buruh Angkut Barang', 'Manually move freight, stock, luggage, or other materials, or perform other general labor. Includes all manual laborers not elsewhere classified.', 1, NULL, NULL, NULL, '53-7062.00', 'Laborers and Freight, Stock, and Material Movers, Hand', 'Laborer;Material Mover', 2, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Pekerja Daur Ulang dan Reklamasi', 'Prepare and sort materials or products for recycling. Identify and remove hazardous substances. Dismantle components of products such as appliances.', 1, NULL, NULL, NULL, '53-7062.04', 'Recycling and Reclamation Workers', 'Recycling and Reclamation Worker', 2, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Operator Pengumpan Mesin', 'Feed materials into or remove materials from machines or equipment that is automatic or tended by other workers.', 1, NULL, NULL, NULL, '53-7063.00', 'Machine Feeders and Offbearers', 'Machine Feeder;Offbearer', 2, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Pengepak Barang (Manual)', 'Pack or package by hand a wide variety of products and materials.', 1, NULL, NULL, NULL, '53-7064.00', 'Packers and Packagers, Hand', 'Packer;Packager', 2, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Petugas Gudang dan Pemenuhan Pesanan', 'Receive, store, and issue merchandise, materials, equipment, and other items from stockroom, warehouse, or storage yard to fill shelves, racks, tables, or customers'' orders. May operate power equipment to fill orders. May mark prices on merchandise and set up sales displays.', 1, NULL, NULL, NULL, '53-7065.00', 'Stockers and Order Fillers', 'Stocker;Order Filler', 2, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Operator Stasiun Kompresor Gas', 'Operate steam-, gas-, electric motor-, or internal combustion-engine driven compressors. Transmit, compress, or recover gases, such as butane, nitrogen, hydrogen, and natural gas.', 1, NULL, NULL, NULL, '53-7071.00', 'Gas Compressor and Gas Pumping Station Operators', 'Gas Compressor Operator;Gas Pumping Station Operator', 2, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Operator Pompa', 'Tend, control, or operate power-driven, stationary, or portable pumps and manifold systems to transfer gases, oil, other liquids, slurries, or powdered materials to and from various vessels and processes.', 1, NULL, NULL, NULL, '53-7072.00', 'Pump Operators, Except Wellhead Pumpers', 'Pump Operator', 2, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Operator Pompa Sumur (Wellhead Pumper)', 'Operate power pumps and auxiliary equipment to produce flow of oil or gas from wells in oil field.', 1, NULL, NULL, NULL, '53-7073.00', 'Wellhead Pumpers', 'Wellhead Pumper', 2, 'umum', 'onet', true, NULL, 'none', NULL),
  ('Petugas Pengumpul Sampah dan Daur Ulang', 'Collect and dump refuse or recyclable materials from containers into truck. May drive truck.', 1, NULL, NULL, NULL, '53-7081.00', 'Refuse and Recyclable Material Collectors', 'Refuse Collector;Waste Collector', 2, 'umum', 'onet', true, NULL, 'none', NULL)
) as v(career_name, career_description, min_education_rank, location_bias,
       salary_min, salary_max, soc_code, name_en, name_alt, job_zone,
       relevance, source, is_active, salary_source, salary_confidence, curation_note)
on conflict (soc_code) where source = 'onet' do nothing;

-- ---------------------------------------------------------------------------
-- 4. Relasi profesi <-> industri (many-to-many)
-- ---------------------------------------------------------------------------
create table if not exists public.career_industries (
  career_id    integer not null references public.careers(id) on delete cascade,
  industry_code text   not null references public.industries(code) on delete cascade,
  primary key (career_id, industry_code)
);
create index if not exists idx_ci_industry on public.career_industries(industry_code);

