-- ---------------------------------------------------------------------------
-- 5. Perluas view career_riasec
--
--    Versi di 0002 join lewat career_onet_map, jadi hanya mencakup 35 profesi
--    IT lama. Profesi hasil impor menyimpan soc_code langsung di kolomnya, dan
--    tanpa perubahan ini 533 profesi baru tidak akan punya skor RIASEC sama
--    sekali -- matching minat diam-diam hanya bekerja untuk sektor IT.
--
--    `confidence` diambil dari career_onet_map bila ada; untuk baris hasil
--    impor nilainya 'high' karena soc_code-nya memang berasal dari O*NET
--    (bukan hasil pemetaan manual yang bisa meleset).
-- ---------------------------------------------------------------------------
create or replace view public.career_riasec
  with (security_invoker = true) as
select
  c.id            as career_id,
  c.career_name,
  c.soc_code,
  coalesce(m.confidence, case when c.source = 'onet' then 'high' else null end) as confidence,
  o.title         as onet_title,
  o.r_raw, o.i_raw, o.a_raw, o.s_raw, o.e_raw, o.c_raw,
  o.r_pct, o.i_pct, o.a_pct, o.s_pct, o.e_pct, o.c_pct,
  o.holland_code
from public.careers c
join public.onet_occupations o on o.soc_code = c.soc_code
left join public.career_onet_map m on m.career_id = c.id
where c.soc_code is not null;

-- ---------------------------------------------------------------------------
-- 6. Rapikan hasil impor
-- ---------------------------------------------------------------------------

-- O*NET punya kategori sisa "..., All Other" untuk menampung okupasi yang tidak
-- masuk kategori lain. Itu bukan nama jabatan nyata -- tidak ada orang bercita-cita
-- jadi "Profesi Teknologi Informasi Lainnya" -- dan O*NET sendiri tidak memberi
-- skor minat untuk kategori ini. Matikan supaya tidak pernah muncul sebagai
-- rekomendasi atau career goal. Barisnya tetap disimpan untuk kelengkapan.
update public.careers
set is_active = false,
    curation_note = trim(both '; ' from coalesce(curation_note,'') ||
                    '; kategori sisa O*NET, tidak punya skor RIASEC')
where source = 'onet' and name_en ilike '%, All Other%';

-- Nama tampilan harus unik supaya user tidak melihat dua kartu yang identik.
update public.careers set career_name = 'Bidan (Perawat Kebidanan)'
  where soc_code = '29-1161.00' and source = 'onet';
update public.careers set career_name = 'Logistics Analyst'
  where soc_code = '13-1081.02' and source = 'onet';

-- ---------------------------------------------------------------------------
-- 7. RLS
-- ---------------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array['industries','career_industries']
  loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists %I on public.%I', t || '_read_all', t);
    execute format('create policy %I on public.%I for select to anon, authenticated using (true)',
                   t || '_read_all', t);
  end loop;
end $$;

commit;

