--   from industries i
--   join career_industries ci on ci.industry_code = i.code
--   join careers c on c.id = ci.career_id
--   group by i.name_id order by 3 desc;
--
--   -- profesi lintas industri
--   select c.career_name, count(*) n from careers c
--   join career_industries ci on ci.career_id = c.id
--   group by 1 having count(*) > 1 order by 2 desc;
--
--   -- yang masih perlu ditinjau manusia
--   select career_name, name_en, relevance, curation_note from careers
--   where curation_note ilike '%verifikasi%';
-- ============================================================================
